<script setup>
import { ref,onMounted,watch } from 'vue'
import { api } from '../api'
import { localDate,storageKey } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const props=defineProps({todayOnly:Boolean}),day=ref(localDate()),schedules=ref([]),rows=ref([]),history=ref([]),drafts=ref({}),error=ref(''),notice=ref('')
const form=ref({name:'',frequency:'daily',start:day.value,weekdays:[],interval:1,enabled:true}),editing=ref(null),writes=useWorkflowWrite('plans')
try{drafts.value=JSON.parse(localStorage.getItem(storageKey('plan-drafts:'+day.value))||'{}')}catch{}
watch(drafts,value=>localStorage.setItem(storageKey('plan-drafts:'+day.value),JSON.stringify(value)),{deep:true})
async function load(){try{const [all,today,past]=await Promise.all([api.flow('/plan-schedules'),api.flow(props.todayOnly?'/plan-occurrences?today=true':'/plan-occurrences?day='+day.value),api.flow('/plan-occurrences')]);schedules.value=all;rows.value=today.items;history.value=past.history;for(const item of rows.value)if(!drafts.value[item.schedule.id])drafts.value[item.schedule.id]={outcome:'done',content:'',actual:null,unit:'',event_id:null,event_version:null,correction:false,reason:''}}catch(e){error.value=e.message}}
async function act(fn){if(writes.busy.value)return;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}}
async function save(){await act(async()=>{await writes.send('/plan-schedules'+(editing.value?'/'+editing.value.id:''),{...form.value,expected_version:editing.value?.version||0},editing.value?'PUT':'POST');form.value={name:'',frequency:'daily',start:day.value,weekdays:[],interval:1,enabled:true};editing.value=null;await load();notice.value='日程已保存。'})}
async function result(item){await act(async()=>{const input=drafts.value[item.schedule.id];await writes.send(`/plan-schedules/${item.schedule.id}/occurrences/${item.local_date||day.value}`,{...input,actual:input.actual===''?null:input.actual,event_id:input.event_id||null,event_version:input.event_version||null,schedule_version:item.schedule.version,expected_version:item.occurrence?.version||0},'PUT');await load();if(input.outcome==='missed')notice.value='';else notice.value='实际事实已保存；分析后再主动确认入账。'})}
function edit(row){editing.value=row;form.value={name:row.name,...row.rule,start:localDate(),enabled:row.enabled};delete form.value.timezone}
onMounted(load)
</script>
<template><section class="card plan-agenda"><h2>{{ todayOnly?'今天到期的计划':'计划日程' }}</h2><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="writes.pending.value">上次结果未知，再次操作将恢复原请求。</p>
<template v-if="!todayOnly"><details><summary>{{ editing?'编辑日程':'创建日程' }}</summary><form @submit.prevent="save"><label>计划名称<input v-model="form.name" maxlength="120" required/></label><label>{{ editing?'修改生效日期':'开始日期' }}<input type="date" v-model="form.start" required/></label><label>周期<select v-model="form.frequency"><option value="daily">每天</option><option value="weekdays">指定星期</option><option value="interval">间隔日</option></select></label><div v-if="form.frequency==='weekdays'" class="action-group"><label v-for="(name,i) in ['一','二','三','四','五','六','日']" :key="i"><input type="checkbox" :value="i" v-model="form.weekdays"/>周{{ name }}</label></div><label v-if="form.frequency==='interval'">间隔天数<input type="number" min="1" max="366" v-model.number="form.interval"/></label><label><input type="checkbox" v-model="form.enabled"/>启用</label><button class="btn primary" :disabled="writes.busy.value">保存日程</button></form></details><details><summary>全部日程 · {{ schedules.length }}</summary><article v-for="row in schedules" :key="row.id"><b>{{ row.name }}</b> · {{ {daily:'每天',weekdays:'指定星期',interval:'间隔日'}[row.rule.frequency] }} · {{ row.enabled?'启用':'已停用' }}<button class="btn" @click="edit(row)">编辑周期 / 停用</button><details><summary>周期历史</summary><p v-for="rev in row.history" :key="rev.version">v{{ rev.version }} · {{ rev.rule.start }} 生效 · {{ {daily:'每天',weekdays:'指定星期',interval:'间隔日'}[rev.rule.frequency] }}</p></details></article></details><label>查看安排日期<input type="date" v-model="day" @change="load"/></label></template>
<p v-if="!rows.length" class="muted">这一天没有到期安排。总表保留其他计划，未操作不算未完成。</p>
<article v-for="item in rows" :key="item.schedule.id" class="plan-card"><h3>{{ item.schedule.name }}</h3><p class="muted">{{ item.local_date||day }} · {{ item.schedule.rule.timezone }}</p><p v-if="item.occurrence">{{ {done:'完成',partial:'部分完成',missed:'未完成'}[item.occurrence.outcome] }} · 已锁定 v{{ item.occurrence.version }}</p><template v-if="drafts[item.schedule.id]"><template v-if="!item.occurrence||drafts[item.schedule.id].correction"><label>实际结果<select v-model="drafts[item.schedule.id].outcome"><option value="done">完成</option><option value="partial">部分完成</option><option value="missed">未完成</option></select></label><template v-if="drafts[item.schedule.id].outcome!=='missed'"><label>实际事实<textarea v-model="drafts[item.schedule.id].content" rows="3"/></label><div class="form-grid"><label>实际量（可空，不默认比例）<input type="number" min="0" step="any" v-model.number="drafts[item.schedule.id].actual"/></label><label>单位<input v-model="drafts[item.schedule.id].unit" maxlength="40"/></label></div><details><summary>关联已保存事件，避免重复记录</summary><label>事件 ID<input type="number" v-model.number="drafts[item.schedule.id].event_id"/></label><label>事件内容版本<input type="number" v-model.number="drafts[item.schedule.id].event_version"/></label></details></template><label v-if="drafts[item.schedule.id].correction">纠错原因<textarea v-model="drafts[item.schedule.id].reason"/></label><button class="btn" :disabled="writes.busy.value" @click="result(item)">{{ drafts[item.schedule.id].outcome==='missed'?'确认未完成并锁定':'保存实际事实' }}</button></template><button v-else class="btn" @click="drafts[item.schedule.id].correction=true">显式纠错</button></template><RouterLink v-if="item.occurrence?.event_id" :to="'/events/'+item.occurrence.event_id">查看事实、分析与入账 →</RouterLink></article>
<details v-if="!todayOnly"><summary>当次历史</summary><article v-for="row in history" :key="row.id"><b>{{ row.local_date }} · {{ row.schedule_snapshot.name }}</b><p>{{ {done:'完成',partial:'部分完成',missed:'未完成'}[row.outcome] }} · 实际量 {{ row.facts.actual??'未填' }} {{ row.facts.unit }}</p><details><summary>更正记录</summary><p v-for="rev in row.history" :key="rev.version">v{{ rev.version }} · {{ {done:'完成',partial:'部分完成',missed:'未完成'}[rev.outcome] }} · {{ rev.facts.correction_reason }}{{ rev.prior_booking_retained?' · 原结算保留':'' }}</p></details></article></details></section></template>
